/bin/zsh -lc "node -e '
const fs=require(\"fs\");
function tsv(p){const [h,...rows]=fs.readFileSync(p,\"utf8\").trimEnd().split(/\\r?\\n/).map(x=>x.split(\"\\t\")); return rows.map((r,i)=>{if(r.length"'!==h.length) throw Error(`${p}:${i+2} column mismatch`); return Object.fromEntries(h.map((k,j)=>[k,r[j]]));});}
const accounts=tsv("accounts.tsv"), txns=tsv("transactions.tsv");
const ids=[...new Set(accounts.map(x=>x.dataset_id))]; if(ids.length!==1) throw Error("account dataset mismatch");
const dataset_id=ids[0], known=new Set(accounts.map(x=>x.account)); if(known.size!==accounts.length) throw Error("duplicate account");
const rejected=txns.filter(x=>x.dataset_id!==dataset_id||!known.has(x.account));
if(rejected.length) throw Error(`rejected transactions: ${JSON.stringify(rejected)}`);
const totals=Object.fromEntries(accounts.map(x=>[x.account,0]));
for(const x of txns){if(!/''^-?'"\\d+"'$/.test(x.delta_cents)) throw Error(`invalid delta ${x.txn_id}`); totals[x.account]+=Number(x.delta_cents);}
const rows=accounts.map(x=>{for(const k of ["opening_cents","declared_closing_cents"]) if(!/''^-?'"\\d+"'$/.test(x[k])) throw Error(`invalid ${k} ${x.account}`); const opening_cents=Number(x.opening_cents), declared_closing_cents=Number(x.declared_closing_cents), transaction_total_cents=totals[x.account], calculated_closing_cents=opening_cents+transaction_total_cents; return {account:x.account,opening_cents,transaction_total_cents,calculated_closing_cents,declared_closing_cents,difference_cents:calculated_closing_cents-declared_closing_cents};}).sort((a,b)=>a.account.localeCompare(b.account));
const ds=rows.filter(x=>x.difference_cents!==0).sort((a,b)=>Math.abs(b.difference_cents)-Math.abs(a.difference_cents)||a.account.localeCompare(b.account));
console.log(JSON.stringify({dataset_id,transaction_count:txns.length,accounts:rows,discrepancy_accounts:ds,total_difference_cents:rows.reduce((s,x)=>s+x.difference_cents,0),total_absolute_difference_cents:rows.reduce((s,x)=>s+Math.abs(x.difference_cents),0),all_declared_balances_match:ds.length===0},null,2));
'"'"
